from pybricks.hubs import PrimeHub
from pybricks.parameters import Direction, Port
from pybricks.pupdevices import ColorSensor, ForceSensor, Motor
from pybricks.robotics import DriveBase

# Set up all devices.
prime_hub = PrimeHub()
color_sensor = ColorSensor(Port.E)
Touch_Sensor = ForceSensor(Port.F)
Left = Motor(Port.A, Direction.COUNTERCLOCKWISE)
Right = Motor(Port.B, Direction.CLOCKWISE)
drive_base = DriveBase(Left, Right, 66, 150)
MM_Left = Motor(Port.C, Direction.CLOCKWISE)
MM_Right = Motor(Port.D, Direction.CLOCKWISE)

# Initialize variables.
myWhite = 100
myBlack = 0
targetValue = 50
baseSpeed = 200
turnAmount = 10
mission = 0
max_mission = 3
running = 0
targetAngle = 0
currentAngle = 0
error = 0
correction = 0
Kp = 2


# The main program starts here.
drive_base.use_gyro(True)
drive_base.reset(0, 0)
targetAngle = 0
baseSpeed = 500
while not drive_base.distance() >= 1000:
    currentAngle = drive_base.angle()
    error = targetAngle - currentAngle
    correction = Kp * error
    drive_base.drive(baseSpeed, 0)
drive_base.straight(0)
